{"path": "src/lib/ledger.ts", "content": "import { Store } from './storage/types';
import { sha256 } from '@noble/hashes/sha2.js';
import { utf8ToBytes, bytesToHex } from '@noble/hashes/utils.js';
import { getLedger, setLedger } from './ledgerHelpers';

export interface LedgerEntry {
  seq: number;
  at: string; // ISO timestamp
  kind: string;
  recordId: string;
  data: any;
  prevHash: string;
  hash: string;
}

/** Compute canonical JSON string with deterministic key order (excluding hash). */
function canonicalJson(entry: Omit<LedgerEntry, 'hash'>): string {
  const sorted: any = {};
  const keys = Object.keys(entry).sort();
  for (const k of keys) {
    sorted[k] = (entry as any)[k];
  }
  return JSON.stringify(sorted);
}

/** Compute hash for entry (without hash field). */
function computeHash(entry: Omit<LedgerEntry, 'hash'>): string {
  const json = canonicalJson(entry);
  return bytesToHex(sha256(utf8ToBytes(json)));
}

/** Append a new ledger entry and persist the ledger. */
export async function appendEntryForReceipt(kind: string, recordId: string, data: any, store: Store): Promise<void> {
  const ledger = await getLedger(store);
  const seq = ledger.length ? ledger[ledger.length - 1].seq + 1 : 1;
  const at = new Date().toISOString();
  const prevHash = ledger.length ? ledger[ledger.length - 1].hash : '0'.repeat(64);
  const entryWithoutHash: Omit<LedgerEntry, 'hash'> = { seq, at, kind, recordId, data, prevHash };
  const hash = computeHash(entryWithoutHash);
  const entry: LedgerEntry = { ...entryWithoutHash, hash };
  ledger.push(entry);
  await setLedger(store, ledger);
}

export async function appendEntryForMileage(kind: string, recordId: string, data: any, store: Store): Promise<void> {
  // Same as receipt version
  await appendEntryForReceipt(kind, recordId, data, store);
}

export async function appendEntryForExport(format: 'csv' | 'pdf', code: string, entries: number, headHash: string, store: Store): Promise<void> {
  const ledger = await getLedger(store);
  const seq = ledger.length ? ledger[ledger.length - 1].seq + 1 : 1;
  const at = new Date().toISOString();
  const prevHash = ledger.length ? ledger[ledger.length - 1].hash : '0'.repeat(64);
  const data = { format, code, entries, headHash };
  const entryWithoutHash: Omit<LedgerEntry, 'hash'> = { seq, at, kind: 'export.created', recordId: '', data, prevHash };
  const hash = computeHash(entryWithoutHash);
  const entry: LedgerEntry = { ...entryWithoutHash, hash };
  ledger.push(entry);
  await setLedger(store, ledger);
}
"}

{"path":"src/lib/ledgerVerification.ts","content":"import { Store } from './storage/types';
import { getLedger } from './ledgerHelpers';

export interface LedgerVerificationResult {
  ok: boolean;
  entries: any[];
  firstBadSeq?: number;
  reason?: string;
}

/**
 * Verify the ledger chain.
 */
export async function verifyLedger(store: Store): Promise<LedgerVerificationResult> {
  const entries = await getLedger(store);
  if (!Array.isArray(entries)) {
    return { ok: false, entries: [], reason: 'Ledger entries not an array' };
  }
  let prevHash = '0'.repeat(64);
  for (let i = 0; i < entries.length; i++) {
    const e = entries[i];
    // seq continuity
    const expectedSeq = i + 1;
    if (e.seq !== expectedSeq) {
      return { ok: false, entries, firstBadSeq: e.seq, reason: `Seq mismatch at ${e.seq}` };
    }
    // prevHash match
    if (e.prevHash !== prevHash) {
      return { ok: false, entries, firstBadSeq: e.seq, reason: 'prevHash mismatch' };
    }
    // recompute hash
    const { hash, ...withoutHash } = e;
    const json = JSON.stringify(Object.keys(withoutHash).sort().reduce((obj, key) => ({ ...obj, [key]: (withoutHash as any)[key] }), {}));
    const computed = bytesToHex(sha256(utf8ToBytes(json)));
    if (hash !== computed) {
      return { ok: false, entries, firstBadSeq: e.seq, reason: 'hash mismatch' };
    }
    prevHash = e.hash;
  }
  return { ok: true, entries };
}
"}

