import { sha256 } from '@noble/hashes/sha2';
import { utf8ToBytes, bytesToHex } from '@noble/hashes/utils';
import { getLedger, setLedger } from './ledgerHelpers';

export interface LedgerEntry {
  seq: number;
  at: string; // ISO timestamp
  kind: string;
  recordId: string;
  data: any;
  prevHash: string;
  hash: string;
}

/** Compute canonical JSON string with deterministic key order (excluding hash). */
export function canonicalJson(entry: Omit<LedgerEntry, 'hash'>): string {
  const sorted: any = {};
  const keys = Object.keys(entry).sort();
  for (const k of keys) {
    sorted[k] = (entry as any)[k];
  }
  return JSON.stringify(sorted);
}

/** Compute hash for entry (without hash field). */
export function computeHash(entry: Omit<LedgerEntry, 'hash'>): string {
  const json = canonicalJson(entry);
  return bytesToHex(sha256(utf8ToBytes(json)));
}

/** Append a new ledger entry and persist the ledger. */
export async function appendEntryForReceipt(kind: string, recordId: string, data: any, store: Store): Promise<void> {
  const ledger = await getLedger(store);
  const seq = ledger.length ? ledger[ledger.length - 1].seq + 1 : 1;
  const at = new Date().toISOString();
  const prevHash = ledger.length ? ledger[ledger.length - 1].hash : '0'.repeat(64);
  const entryWithoutHash: Omit<LedgerEntry, 'hash'> = { seq, at, kind, recordId, data, prevHash };
  const hash = computeHash(entryWithoutHash);
  const entry: LedgerEntry = { ...entryWithoutHash, hash };
  ledger.push(entry);
  await setLedger(store, ledger);
}

export async function appendEntryForMileage(kind: string, recordId: string, data: any, store: Store): Promise<void> {
  // Reuse receipt implementation
  await appendEntryForReceipt(kind, recordId, data, store);
}

export async function appendEntryForExport(format: 'csv' | 'pdf', code: string, entriesCount: number, headHash: string, store: Store): Promise<void> {
  const ledger = await getLedger(store);
  const seq = ledger.length ? ledger[ledger.length - 1].seq + 1 : 1;
  const at = new Date().toISOString();
  const prevHash = ledger.length ? ledger[ledger.length - 1].hash : '0'.repeat(64);
  const data = { format, code, entries: entriesCount, headHash };
  const entryWithoutHash: Omit<LedgerEntry, 'hash'> = { seq, at, kind: 'export.created', recordId: '', data, prevHash };
  const hash = computeHash(entryWithoutHash);
  const entry: LedgerEntry = { ...entryWithoutHash, hash };
  ledger.push(entry);
  await setLedger(store, ledger);
}
"}

{"path": "src/lib/ledgerHelpers.ts", "content": "import { Store } from './storage/types';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { LedgerEntry, computeHash } from './ledger';

/** Retrieve the ledger entries array from the encrypted store. */
export async function getLedger(store: Store): Promise<LedgerEntry[]> {
  const ledger = await store.get<LedgerEntry[]>('ledger');
  return ledger ?? [];
}

/** Store the ledger entries array back into the encrypted store. */
export async function setLedger(store: Store, entries: LedgerEntry[]): Promise<void> {
  await store.set('ledger', entries);
}

/**
 * On first launch, import existing receipts and mileage as ledger entries of kind 'imported'.
 * This runs only once: if a ledger already exists, it does nothing.
 */
export async function initLedgerIfNeeded(store: Store): Promise<void> {
  const existing = await store.get<any>('ledger');
  if (existing) return; // ledger already initialized

  const receipts = await getAllReceipts(store);
  const mileage = await getAllMileageEntries(store);

  const entries: LedgerEntry[] = [];
  const importDate = new Date().toISOString();

  const addImported = (recordId: string, data: any) => {
    const seq = entries.length ? entries[entries.length - 1].seq + 1 : 1;
    const prevHash = entries.length ? entries[entries.length - 1].hash : '0'.repeat(64);
    const entryWithoutHash = {
      seq,
      at: importDate,
      kind: 'imported',
      recordId,
      data,
      prevHash,
    } as const;
    const hash = computeHash(entryWithoutHash as any);
    const entry: LedgerEntry = { ...entryWithoutHash, hash } as LedgerEntry;
    entries.push(entry);
  };

  for (const r of receipts) {
    addImported(r.id, r);
  }
  for (const m of mileage) {
    addImported(m.id, m);
  }

  await setLedger(store, entries);
}
"}

{"path": "src/lib/ledgerVerification.ts", "content": "import { Store } from './storage/types';
import { getLedger } from './ledgerHelpers';
import { sha256 } from '@noble/hashes/sha2';
import { utf8ToBytes, bytesToHex } from '@noble/hashes/utils';

export interface LedgerVerificationResult {
  ok: boolean;
  entries: any[];
  firstBadSeq?: number;
  reason?: string;
}

/** Verify the ledger chain */
export async function verifyLedger(store: Store, entries?: any[]): Promise<LedgerVerificationResult> {
  const ledgerEntries = entries ?? (await getLedger(store));
  if (!Array.isArray(ledgerEntries)) {
    return { ok: false, entries: [], reason: 'Ledger entries not an array' };
  }
  let prevHash = '0'.repeat(64);
  for (let i = 0; i < ledgerEntries.length; i++) {
    const e = ledgerEntries[i];
    const expectedSeq = i + 1;
    if (e.seq !== expectedSeq) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: `Seq mismatch at ${e.seq}` };
    }
    if (e.prevHash !== prevHash) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: 'prevHash mismatch' };
    }
    const { hash, ...withoutHash } = e;
    const json = JSON.stringify(Object.keys(withoutHash).sort().reduce((obj, key) => ({ ...obj, [key]: (withoutHash as any)[key] }), {}));
    const computed = bytesToHex(sha256(utf8ToBytes(json)));
    if (hash !== computed) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: 'hash mismatch' };
    }
    prevHash = e.hash;
  }
  return { ok: true, entries: ledgerEntries };
}
"}

{"path": "src/lib/exportCsv.ts", "content": "import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import type { Receipt, MileageEntry } from './models';
import type { Store } from './storage/types';
import { sha256 } from '@noble/hashes/sha2';
import { utf8ToBytes, bytesToHex } from '@noble/hashes/utils';
import { appendEntryForExport } from './ledger';

/** Escape a cell for CSV output according to RFC 4180.
 * Numbers output as plain numbers.
 * null/undefined become empty string.
 * Strings starting with = + - @ or tab are prefixed with a single quote to prevent formula injection.
 * If a string is prefixed, we leave it as‑is (no additional quoting or double‑quote escaping) because the prefix already neutralises formulas.
 * Otherwise, double quotes inside the value are escaped by doubling them.
 * If the resulting string contains commas, double quotes, or line breaks, wrap the whole field in double quotes.
 */
function csvEscape(value: any): string {
  if (value === undefined || value === null) return '';
  if (typeof value === 'number') return String(value);
  const original = String(value);
  const needsPrefix = /^[=+\-@\t]/.test(original);
  if (needsPrefix) {
    return "'" + original;
  }
  // Escape double quotes by doubling them
  const escaped = original.replace(/"/g, '""');
  // Wrap in quotes if contains special chars
  if (/[",\r\n]/.test(escaped)) {
    return `"${escaped}"`;
  }
  return escaped;
}

/** Generate a CSV string containing receipts and mileage entries, with a verification line.
 * Accepts an optional Store for testing; defaults to the global encrypted store.
 */
export async function generateCsv(store?: Store): Promise<string> {
  let s = store;
  if (!s) {
    try {
      const { getStore } = require('./storage');
      s = getStore();
    } catch {
      s = null as any;
    }
  }
  const receipts: Receipt[] = s ? await getAllReceipts(s) : [];
  const mileage: MileageEntry[] = s ? await getAllMileageEntries(s) : [];
  const lines: string[] = [];
  // Header for receipts
  lines.push('id,amount,date,category,type,notes');
  for (const r of receipts) {
    lines.push([
      csvEscape(r.id),
      csvEscape(r.amount),
      csvEscape(r.date),
      csvEscape(r.category),
      csvEscape(r.type),
      csvEscape(r.notes),
    ].join(','));
  }
  // Header for mileage
  lines.push('id,miles,date,purpose');
  for (const m of mileage) {
    lines.push([
      csvEscape(m.id),
      csvEscape(m.miles),
      csvEscape(m.date),
      csvEscape(m.purpose),
    ].join(','));
  }
  // verification line
  const contentWithoutVerification = lines.join('\n');
  const hashHex = bytesToHex(sha256(utf8ToBytes(contentWithoutVerification)));
  const code = hashHex.slice(0, 12);
  const entriesCount = (await (await import('./ledgerHelpers')).getLedger(s ?? (await (await import('./storage')).getStore()))
    .length + 1; // after this export entry
  const headHash = (await (await import('./ledgerHelpers')).getLedger(s ?? (await (await import('./storage')).getStore()))
    .slice(-1)[0]?.hash ?? '0'.repeat(64);
  // Append ledger entry for export
  await appendEntryForExport('csv', code, entriesCount, headHash, s);
  lines.push(`# verification: entries=${entriesCount}, headHash=${headHash}, code=${code}`);
  return lines.join('\n');
}
"}

{"path": "src/lib/exportVerification.ts", "content": "import { Store } from './storage/types';
import { getLedger } from './ledgerHelpers';
import { LedgerEntry } from './ledger';

/** Verify an export code against ledger entries.
 * Returns whether the code is known, the number of entries and head hash from the matching export entry,
 * and whether there have been later ledger entries after that export (i.e., later changes).
 */
export async function verifyExportCode(code: string, store: Store): Promise<{ known: boolean; entries?: number; headHash?: string; laterChanges?: boolean }> {
  const ledger = await getLedger(store);
  const entry = ledger.find((e: LedgerEntry) => e.kind === 'export.created' && e.data?.code === code);
  if (!entry) {
    return { known: false };
  }
  const laterChanges = ledger.some((e: LedgerEntry) => e.seq > entry.seq);
  return { known: true, entries: entry.data?.entries, headHash: entry.data?.headHash, laterChanges };
}
"}

