{"path": "src/screens/VerifyExportScreen.tsx", "content": "import React, { useState } from 'react';
import { View, ActivityIndicator } from 'react-native';
import { Screen, PrimaryButton, TextInput } from '../components/ui';
import { verifyExportCode } from '../lib/exportVerification';
import { getStore } from '../lib/storage';

export default function VerifyExportScreen() {
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  const check = async () => {
    setLoading(true);
    const res = await verifyExportCode(code, getStore());
    setResult(res);
    setLoading(false);
  };

  return (
    <Screen title="Verify export">
      <TextInput label="Verification code" value={code} onChangeText={setCode} />
      <PrimaryButton label="Check" onPress={check} disabled={loading} />
      {loading && <ActivityIndicator />}
      {result && (
        <View style={{ marginTop: 12 }}>
          <View><Text>{result.known ? 'Code known' : 'Code not found'}</Text></View>
          {result.laterChanges && <View><Text>Later changes detected</Text></View>}
        </View>
      )}
    </Screen>
  );
}
"}

{"path":"src/screens/SettingsScreen.tsx","content":"import React, { useEffect, useState } from 'react';
import { Card } from 'react-native-paper';
import { PrimaryButton, Screen, SettingSwitch } from '../components/ui';
import { theme } from '../theme';
import { getAppLockEnabled, setAppLockEnabled } from '../lib/settings';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { getStore } from '../lib/storage';
import { verifyLedger } from '../lib/ledgerVerification';
import VerificationStatus from '../components/ui/VerificationStatus';

/** Settings screen with links to sub‑screens and actions. */
export default function SettingsScreen({ onViewPolicy }: { onViewPolicy?: () => void }) {
  const navigation = useNavigation<NavigationProp<any>>();
  const [lock, setLock] = useState(false);
  const [ledgerInfo, setLedgerInfo] = useState<{ ok: boolean; entries: any[] } | null>(null);

  useEffect(() => {
    (async () => {
      const v = await getAppLockEnabled();
      setLock(v);
      const verification = await verifyLedger(getStore());
      setLedgerInfo({ ok: verification.ok, entries: verification.entries });
    })();
  }, []);

  const toggleLock = async (value: boolean) => {
    setLock(value);
    await setAppLockEnabled(value);
  };

  const deleteAllData = () => {
    navigation.navigate('DeleteAllData' as any);
  };

  const goCategories = () => {
    navigation.navigate('Categories' as any);
  };

  const goVerifyExport = () => {
    navigation.navigate('VerifyExport' as any);
  };

  return (
    <Screen title="Settings">
      <Card mode="outlined" style={{ backgroundColor: theme.colors.surface, marginBottom: 12 }}>
        <SettingSwitch
          label="App lock"
          description="Require biometric authentication on launch"
          value={lock}
          onChange={toggleLock}
        />
      </Card>
      {ledgerInfo && (
        <VerificationStatus ok={ledgerInfo.ok} entryCount={ledgerInfo.entries.length} />
      )}
      <PrimaryButton label="App lock" variant="secondary" onPress={() => navigation.navigate('AppLock')} />
      <PrimaryButton label="Tax settings" variant="secondary" onPress={() => navigation.navigate('TaxSettings')} />
      <PrimaryButton label="Categories" variant="secondary" onPress={goCategories} />
      <PrimaryButton label="Export" variant="secondary" onPress={() => navigation.navigate('Export')} />
      <PrimaryButton label="Backup & restore" variant="secondary" onPress={() => navigation.navigate('Backup')} />
      <PrimaryButton label="Verify export" variant="secondary" onPress={goVerifyExport} />
      <PrimaryButton label="Delete all data" variant="secondary" onPress={deleteAllData} />
      <PrimaryButton label="View Terms and Privacy Policy" variant="secondary" onPress={onViewPolicy ?? (() => {})} />
    </Screen>
  );
}
"}

{"path": "src/navigation/index.tsx", "content": "import React from 'react';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { NavigationContainer, DefaultTheme } from '@react-navigation/native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import DashboardScreen from '../screens/DashboardScreen';
import ReceiptsScreen from '../screens/ReceiptsScreen';
import SettingsScreen from '../screens/SettingsScreen';
import PolicyScreen from '../screens/PolicyScreen';
import ReceiptEntryScreen from '../screens/ReceiptEntryScreen';
import MileageScreen from '../screens/MileageScreen';
import MileageEntryScreen from '../screens/MileageEntryScreen';
import AppLockScreen from '../screens/AppLockScreen';
import TaxSettingsScreen from '../screens/TaxSettingsScreen';
import ExportScreen from '../screens/ExportScreen';
import BackupScreen from '../screens/BackupScreen';
import BackupPassphraseScreen from '../screens/BackupPassphraseScreen';
import RestoreScreen from '../screens/RestoreScreen';
import DeleteAllDataScreen from '../screens/DeleteAllDataScreen';
import BackupSuccessScreen from '../screens/BackupSuccessScreen';
import RestoreSuccessScreen from '../screens/RestoreSuccessScreen';
import CategoriesScreen from '../screens/CategoriesScreen';
import ReceiptDetailScreen from '../screens/ReceiptDetailScreen';
import ReceiptHistoryScreen from '../screens/ReceiptHistoryScreen';
import MileageHistoryScreen from '../screens/MileageHistoryScreen';
import VerifyExportScreen from '../screens/VerifyExportScreen';
import { theme } from '../theme';

const Tab = createBottomTabNavigator();
const Stack = createNativeStackNavigator();
const SettingsStack = createNativeStackNavigator();

const tabIcon = (name: React.ComponentProps<typeof MaterialCommunityIcons>['name']) =>
  ({ color, size }: { color: string; size: number }) => <MaterialCommunityIcons name={name} color={color} size={size} aria-hidden />;

function SettingsStackScreen() {
  return (
    <SettingsStack.Navigator initialRouteName="SettingsMain">
      <SettingsStack.Screen name="SettingsMain" component={SettingsScreen} options={{ headerShown: false }} />
      <SettingsStack.Screen name="Categories" component={CategoriesScreen} options={{ title: 'Categories' }} />
      <SettingsStack.Screen name="Export" component={ExportScreen} options={{ title: 'Export data' }} />
      <SettingsStack.Screen name="Backup" component={BackupScreen} options={{ title: 'Backup & restore' }} />
      <SettingsStack.Screen name="backup_passphrase_modal" component={BackupPassphraseScreen} options={{ title: 'Create backup' }} />
      <SettingsStack.Screen name="backup_success" component={BackupSuccessScreen} options={{ title: 'Backup' }} />
      <SettingsStack.Screen name="restore_passphrase_modal" component={RestoreScreen} options={{ title: 'Restore backup' }} />
      <SettingsStack.Screen name="restore_success" component={RestoreSuccessScreen} options={{ title: 'Restore success' }} />
      <SettingsStack.Screen name="AppLock" component={AppLockScreen} options={{ title: 'App lock' }} />
      <SettingsStack.Screen name="TaxSettings" component={TaxSettingsScreen} options={{ title: 'Tax settings' }} />
      <SettingsStack.Screen name="DeleteAllData" component={DeleteAllDataScreen} options={{ title: 'Delete all data' }} />
      <SettingsStack.Screen name="ReceiptDetail" component={ReceiptDetailScreen} />
      <SettingsStack.Screen name="ReceiptHistory" component={ReceiptHistoryScreen} />
      <SettingsStack.Screen name="MileageHistory" component={MileageHistoryScreen} />
      <SettingsStack.Screen name="VerifyExport" component={VerifyExportScreen} options={{ title: 'Verify export' }} />
    </SettingsStack.Navigator>
  );
}

function Tabs() {
  return (
    <Tab.Navigator
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: theme.colors.primary,
        tabBarInactiveTintColor: theme.colors.secondary,
        tabBarStyle: { backgroundColor: theme.colors.surface, height: 64, paddingTop: 6, paddingBottom: 8 },
        tabBarLabelStyle: { fontSize: 12, fontWeight: '500' },
      }}
    >
      <Tab.Screen
        name="Dashboard"
        component={DashboardScreen}
        options={{
          tabBarIcon: tabIcon('view-dashboard-outline'),
          tabBarLabel: 'Dashboard',
          tabBarAccessibilityLabel: 'Dashboard',
        }}
      />
      <Tab.Screen
        name="Receipts"
        component={ReceiptsScreen}
        options={{
          tabBarIcon: tabIcon('receipt-outline'),
          tabBarLabel: 'Receipts',
          tabBarAccessibilityLabel: 'Receipts',
        }}
      />
      <Tab.Screen
        name="Mileage"
        component={MileageScreen}
        options={{
          tabBarIcon: tabIcon('run'),
          tabBarLabel: 'Mileage',
          tabBarAccessibilityLabel: 'Mileage',
        }}
      />
      <Tab.Screen
        name="Settings"
        component={SettingsStackScreen}
        options={{
          tabBarIcon: tabIcon('cog-outline'),
          tabBarLabel: 'Settings',
          tabBarAccessibilityLabel: 'Settings',
        }}
      />
    </Tab.Navigator>
  );
}

const navTheme = { ...DefaultTheme, colors: { ...DefaultTheme.colors, background: theme.colors.background, primary: theme.colors.primary } };

export default function Navigation() {
  return (
    <NavigationContainer theme={navTheme}>
      <Stack.Navigator>
        <Stack.Screen name="Main" component={Tabs} options={{ headerShown: false }} />
        <Stack.Screen name="Policy" options={{ title: 'Terms and Privacy Policy' }}>
          {() => <PolicyScreen readOnly onAccept={() => {}} />}
        </Stack.Screen>
        <Stack.Screen name="ReceiptEntry" options={{ title: 'Add receipt' }} component={ReceiptEntryScreen} />
        <Stack.Screen name="MileageEntry" options={{ title: 'Add mileage' }} component={MileageEntryScreen} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}
"}

{"path":"src/components/ui/ReceiptCard.tsx","content":"import React from 'react';
