{"path":"src/lib/exportCsv.ts","content":"import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import type { Receipt, MileageEntry } from './models';
import type { Store } from './storage/types';
import { sha256 } from '@noble/hashes/sha2.js';
import { utf8ToBytes, bytesToHex } from '@noble/hashes/utils.js';
import { appendEntryForExport } from './ledger';
import { getLedger } from './ledgerHelpers';

/** Escape a cell for CSV output according to RFC 4180.
 * Numbers output as plain numbers.
 * null/undefined become empty string.
 * Strings starting with = + - @ or tab are prefixed with a single quote to prevent formula injection.
 * If a string is prefixed, we leave it as-is (no additional quoting) because the prefix already neutralises formulas.
 * Otherwise, double quotes inside the value are escaped by doubling them.
 * If the resulting string contains commas, double quotes, or line breaks, wrap the whole field in double quotes.
 */
function csvEscape(value: any): string {
  if (value === undefined || value === null) return '';
  if (typeof value === 'number') return String(value);
  const original = String(value);
  const needsPrefix = /^[=+\-@\t]/.test(original);
  if (needsPrefix) {
    return "'" + original;
  }
  const escaped = original.replace(/"/g, '""');
  if (/[",\r\n]/.test(escaped)) {
    return `"${escaped}"`;
  }
  return escaped;
}

/** Generate a CSV string containing receipts and mileage entries, with a verification line formatted as
 * "# verification: entries=<N>, headHash=<HASH>, code=<CODE>".
 * The code is the first 12 hex characters of the hash of the CSV content without the verification line.
 */
export async function generateCsv(store?: Store): Promise<string> {
  const s = store ?? (await (await import('./storage')).getStore());
  const receipts: Receipt[] = await getAllReceipts(s);
  const mileage: MileageEntry[] = await getAllMileageEntries(s);
  const lines: string[] = [];
  lines.push('id,amount,date,category,type,notes');
  for (const r of receipts) {
    lines.push([
      csvEscape(r.id),
      csvEscape(r.amount),
      csvEscape(r.date),
      csvEscape(r.category),
      csvEscape(r.type),
      csvEscape(r.notes),
    ].join(','));
  }
  lines.push('id,miles,date,purpose');
  for (const m of mileage) {
    lines.push([
      csvEscape(m.id),
      csvEscape(m.miles),
      csvEscape(m.date),
      csvEscape(m.purpose),
    ].join(','));
  }
  const contentWithoutVerification = lines.join('\n');
  const hashHex = bytesToHex(sha256(utf8ToBytes(contentWithoutVerification)));
  const code = hashHex.slice(0, 12);
  const ledger = await getLedger(s);
  const entriesCount = ledger.length + 1;
  const headHash = ledger.length ? ledger[ledger.length - 1].hash : '0'.repeat(64);
  await appendEntryForExport('csv', code, entriesCount, headHash, s);
  const verificationLine = `# verification: entries=${entriesCount}, headHash=${headHash}, code=${code}`;
  lines.push(verificationLine);
  return lines.join('\n');
}
"}

{"path":"src/lib/ledger.ts","content":"import { Store } from './storage/types';
import { sha256 } from '@noble/hashes/sha2.js';
import { utf8ToBytes, bytesToHex } from '@noble/hashes/utils.js';
import { getLedger, setLedger } from './ledgerHelpers';

export interface LedgerEntry {
  seq: number;
  at: string; // ISO timestamp
  kind: string;
  recordId: string;
  data: any;
  prevHash: string;
  hash: string;
}

/** Compute canonical JSON string with deterministic key order (excluding hash). */
export function canonicalJson(entry: Omit<LedgerEntry, 'hash'>): string {
  const sorted: any = {};
  const keys = Object.keys(entry).sort();
  for (const k of keys) {
    sorted[k] = (entry as any)[k];
  }
  return JSON.stringify(sorted);
}

/** Compute hash for entry (without hash field). */
export function computeHash(entry: Omit<LedgerEntry, 'hash'>): string {
  const json = canonicalJson(entry);
  return bytesToHex(sha256(utf8ToBytes(json)));
}

/** Append a new ledger entry and persist the ledger. */
export async function appendEntryForReceipt(kind: string, recordId: string, data: any, store: Store): Promise<void> {
  const ledger = await getLedger(store);
  const seq = ledger.length ? ledger[ledger.length - 1].seq + 1 : 1;
  const at = new Date().toISOString();
  const prevHash = ledger.length ? ledger[ledger.length - 1].hash : '0'.repeat(64);
  const entryWithoutHash: Omit<LedgerEntry, 'hash'> = { seq, at, kind, recordId, data, prevHash };
  const hash = computeHash(entryWithoutHash);
  const entry: LedgerEntry = { ...entryWithoutHash, hash };
  ledger.push(entry);
  await setLedger(store, ledger);
}

export async function appendEntryForMileage(kind: string, recordId: string, data: any, store: Store): Promise<void> {
  await appendEntryForReceipt(kind, recordId, data, store);
}

/** Append an export.created ledger entry and store relevant data. */
export async function appendEntryForExport(format: 'csv' | 'pdf', code: string, entriesCount: number, headHashPrev: string, store: Store): Promise<void> {
  const ledger = await getLedger(store);
  const seq = ledger.length ? ledger[ledger.length - 1].seq + 1 : 1;
  const at = new Date().toISOString();
  const prevHash = ledger.length ? ledger[ledger.length - 1].hash : '0'.repeat(64);
  // data includes format, code, entries (seq), headHash (prevHash)
  const data: any = { format, code, entries: entriesCount, headHash: headHashPrev };
  const entryWithoutHash: Omit<LedgerEntry, 'hash'> = { seq, at, kind: 'export.created', recordId: '', data, prevHash };
  const hash = computeHash(entryWithoutHash);
  const entry: LedgerEntry = { ...entryWithoutHash, hash };
  ledger.push(entry);
  await setLedger(store, ledger);
}
"}

