{"path":"src/lib/ledgerVerification.ts","content":"import { Store } from './storage/types';
import { getLedger } from './ledgerHelpers';
import { sha256, utf8ToBytes, bytesToHex } from '@noble/hashes/sha2.js';

export interface LedgerVerificationResult {
  ok: boolean;
  entries: any[];
  firstBadSeq?: number;
  reason?: string;
}

/** Verify the ledger chain */
export async function verifyLedger(store: Store, entries?: any[]): Promise<LedgerVerificationResult> {
  const ledgerEntries = entries ?? (await getLedger(store));
  if (!Array.isArray(ledgerEntries)) {
    return { ok: false, entries: [], reason: 'Ledger entries not an array' };
  }
  let prevHash = '0'.repeat(64);
  for (let i = 0; i < ledgerEntries.length; i++) {
    const e = ledgerEntries[i];
    const expectedSeq = i + 1;
    if (e.seq !== expectedSeq) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: `Seq mismatch at ${e.seq}` };
    }
    if (e.prevHash !== prevHash) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: 'prevHash mismatch' };
    }
    const { hash, ...withoutHash } = e;
    const json = JSON.stringify(Object.keys(withoutHash).sort().reduce((obj, key) => ({ ...obj, [key]: (withoutHash as any)[key] }), {}));
    const computed = bytesToHex(sha256(utf8ToBytes(json)));
    if (hash !== computed) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: 'hash mismatch' };
    }
    prevHash = e.hash;
  }
  return { ok: true, entries: ledgerEntries };
}
"}

{"path": "src/screens/ReceiptDetailScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { View, ActivityIndicator } from 'react-native';
import { Screen, PrimaryButton, EmptyState } from '../components/ui';
import { getStore } from '../lib/storage';
import { getAllReceipts } from '../lib/receiptStore';
import { useNavigation, useRoute, NavigationProp } from '@react-navigation/native';

export default function ReceiptDetailScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const route = useRoute<any>();
  const { recordId } = route.params ?? {};
  const [loading, setLoading] = useState(true);
  const [receipt, setReceipt] = useState<any>(null);

  useEffect(() => {
    (async () => {
      const all = await getAllReceipts(getStore());
      const r = all.find((r) => r.id === recordId);
      setReceipt(r);
      setLoading(false);
    })();
  }, [recordId]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading receipt"/>;
  }

  if (!receipt) {
    return (
      <Screen title="Receipt detail">
        <EmptyState
          icon="receipt-outline"
          title="Not found"
          body="Receipt not found"
          actionLabel="Back"
          onAction={() => navigation.goBack()}
        />
      </Screen>
    );
  }

  return (
    <Screen title="Receipt detail">
      <PrimaryButton label="Edit" onPress={() => navigation.navigate('ReceiptEntry' as any)} />
      <PrimaryButton label="History" onPress={() => navigation.navigate('ReceiptHistory' as any, { recordId })} />
    </Screen>
  );
}
"}

{"path":"src/screens/MileageHistoryScreen.tsx","content":"import React, { useEffect, useState } from 'react';
import { ActivityIndicator } from 'react-native';
import { Screen, EmptyState } from '../components/ui';
import { getLedger } from '../lib/ledgerHelpers';
import { useNavigation, useRoute, NavigationProp } from '@react-navigation/native';
import HistoryList from '../components/ui/HistoryList';
import { LedgerEntry } from '../lib/ledger';
import { getStore } from '../lib/storage';

export default function MileageHistoryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const route = useRoute<any>();
  const { recordId } = route.params ?? {};
  const [loading, setLoading] = useState(true);
  const [entries, setEntries] = useState<LedgerEntry[]>([]);

  useEffect(() => {
    (async () => {
      const ledger = await getLedger(getStore());
      const filtered = ledger.filter(e => e.recordId === recordId && e.kind.startsWith('mileage.'));
      setEntries(filtered as any);
      setLoading(false);
    })();
  }, [recordId]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading history..." />;
  }

  if (entries.length === 0) {
    return (
      <Screen title="Mileage history">
        <EmptyState
          icon="history"
          title="No changes yet"
          body="This mileage entry has never been edited."
          actionLabel="Back"
          onAction={() => navigation.goBack()}
        />
      </Screen>
    );
  }

  const items = entries.map(e => ({ date: e.at, kind: e.kind, preview: undefined }));
  return (
    <Screen title="Mileage history">
      <HistoryList entries={items} />
    </Screen>
  );
}
"}

