export async function restoreBackup(store: Store, backupString: string, passphrase: string): Promise<void> {
  const [saltB64, cipher] = backupString.split(':');
  if (!saltB64 || !cipher) throw new Error('Invalid backup format');
  const salt = fromBase64(saltB64);
  const key = deriveKey(passphrase, salt);
  let json: string;
  try {
    json = decryptText(key, cipher);
  } catch (e) {
    throw new Error('Friendly error: unable to decrypt backup. The backup may be corrupted.');
  }
  let obj: any;
  try {
    obj = JSON.parse(json);
  } catch {
    throw new Error('Friendly error: backup data corrupted.');
  }
  const err = validateBackupStructure(obj);
  if (err) throw new Error('Friendly error: ' + err);

  // If ledger present, verify it before applying any changes.
  if (obj.ledger) {
    const verification = await verifyLedger(store, obj.ledger);
    if (!verification.ok) {
      throw new Error('Friendly error: backup ledger verification failed.');
    }
  }

