{"path":"src/lib/ledgerVerification.ts","line_start":1,"line_end":200,"content":"import { Store } from './storage/types';
import { getLedger } from './ledgerHelpers';
import { computeHash } from './ledger';

export interface LedgerVerificationResult {
  ok: boolean;
  entries: any[];
  firstBadSeq?: number;
  reason?: string;
}

/** Verify the ledger chain */
export async function verifyLedger(store: Store, entries?: any[]): Promise<LedgerVerificationResult> {
  const ledgerEntries = entries ?? (await getLedger(store));
  if (!Array.isArray(ledgerEntries)) {
    return { ok: false, entries: [], reason: 'Ledger entries not an array' };
  }
  let prevHash = '0'.repeat(64);
  for (let i = 0; i < ledgerEntries.length; i++) {
    const e = ledgerEntries[i];
    const expectedSeq = i + 1;
    if (e.seq !== expectedSeq) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: `Seq mismatch at ${e.seq}` };
    }
    if (e.prevHash !== prevHash) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: 'prevHash mismatch' };
    }
    const recomputed = computeHash({
      seq: e.seq,
      at: e.at,
      kind: e.kind,
      recordId: e.recordId,
      data: e.data,
      prevHash: e.prevHash,
    } as any);
    if (e.hash !== recomputed) {
      return { ok: false, entries: ledgerEntries, firstBadSeq: e.seq, reason: 'hash mismatch' };
    }
    prevHash = e.hash;
  }
  return { ok: true, entries: ledgerEntries };
}
"}

{"path":"src/lib/ledgerHelpers.ts","line_start":1,"line_end":200,"content":"import { Store } from './storage/types';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { LedgerEntry, computeHash } from './ledger';

/** Retrieve the ledger entries array from the encrypted store. */
export async function getLedger(store: Store): Promise<LedgerEntry[]> {
  const ledger = await store.get<LedgerEntry[]>('ledger');
  return ledger ?? [];
}

/** Store the ledger entries array back into the encrypted store. */
export async function setLedger(store: Store, entries: LedgerEntry[]): Promise<void> {
  await store.set('ledger', entries);
}

/**
 * On first launch, import existing receipts and mileage as ledger entries of kind 'imported'.
 * This runs only once: if a ledger already exists, it does nothing.
 */
export async function initLedgerIfNeeded(store: Store): Promise<void> {
  const existing = await store.get<any>('ledger');
  if (existing) return; // ledger already initialized

  const receipts = await getAllReceipts(store);
  const mileage = await getAllMileageEntries(store);

  const entries: LedgerEntry[] = [];

  const addImported = (recordId: string, data: any) => {
    const seq = entries.length ? entries[entries.length - 1].seq + 1 : 1;
    const prevHash = entries.length ? entries[entries.length - 1].hash : '0'.repeat(64);
    const at = new Date().toISOString();
    const entryWithoutHash = {
      seq,
      at,
      kind: 'imported',
      recordId,
      data,
      prevHash,
    } as const;
    const hash = computeHash(entryWithoutHash as any);
    const entry: LedgerEntry = { ...entryWithoutHash, hash } as LedgerEntry;
    entries.push(entry);
  };

  for (const r of receipts) {
    addImported(r.id, r);
  }
  for (const m of mileage) {
    addImported(m.id, m);
  }

  await setLedger(store, entries);
}

/** Import any missing receipts/mileage as 'imported' entries (used after restore). */
export async function importMissingAsImported(store: Store): Promise<void> {
  const ledger = await getLedger(store);
  const receipts = await getAllReceipts(store);
  const mileage = await getAllMileageEntries(store);

  const hasImported = (recordId: string) => ledger.some(e => e.kind === 'imported' && e.recordId === recordId);

  const entries = [...ledger];

  const addImported = (recordId: string, data: any) => {
    const seq = entries.length ? entries[entries.length - 1].seq + 1 : 1;
    const prevHash = entries.length ? entries[entries.length - 1].hash : '0'.repeat(64);
    const at = new Date().toISOString();
    const entryWithoutHash = {
      seq,
      at,
      kind: 'imported',
      recordId,
      data,
      prevHash,
    } as const;
    const hash = computeHash(entryWithoutHash as any);
    const entry: LedgerEntry = { ...entryWithoutHash, hash } as LedgerEntry;
    entries.push(entry);
  };

  for (const r of receipts) {
    if (!hasImported(r.id)) addImported(r.id, r);
  }
  for (const m of mileage) {
    if (!hasImported(m.id)) addImported(m.id, m);
  }

  await setLedger(store, entries);
}
"}

{"path":"src/lib/exportVerification.ts","line_start":1,"line_end":200,"content":"import { Store } from './storage/types';
import { getLedger } from './ledgerHelpers';
import { LedgerEntry } from './ledger';

/** Verify an export code against ledger entries.
 * Returns whether the code is known, the ledger sequence number of the export entry,
 * the appropriate headHash (previous hash for CSV, entry hash for PDF),
 * whether there have been later ledger entries after that export,
 * and a human‑readable message.
 */
export async function verifyExportCode(
  code: string,
  store: Store,
): Promise<{ known: boolean; entries?: number; headHash?: string; laterChanges?: boolean; message?: string }> {
  const ledger = await getLedger(store);
  // Extract a 12‑char hex code fragment from the input, ignoring any surrounding text.
  const match = code.match(/[0-9a-f]{12}/i);
  const codeFragment = match ? match[0] : '';
  if (!codeFragment) {
    return { known: false, message: 'Invalid verification code format' };
  }
  const entry = ledger.find(
    (e: LedgerEntry) => e.kind === 'export.created' && e.data?.code === codeFragment,
  );
  if (!entry) {
    return { known: false, message: 'Verification code not from this app' };
  }
  const laterChanges = ledger.some((e: LedgerEntry) => e.seq > entry.seq);
  // For both CSV and PDF the headHash stored in the entry data is the entry's own hash.
  const headHash = entry.data?.headHash ?? entry.hash;
  return {
    known: true,
    entries: entry.seq,
    headHash,
    laterChanges,
    message: 'Verification code matches an export created by this app',
  };
}
"}

