{"path":"src/lib/backup.ts","line_start":1,"line_end":300,"content":"import { Store } from './storage/types';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { getAllCategories } from './categories';
import { encryptText, decryptText, deriveKey, randomBytes, toBase64, fromBase64 } from './crypto';
import { verifyLedger } from './ledgerVerification';
import { getLedger, setLedger, importMissingAsImported } from './ledgerHelpers';

/**
 * Backup format version.
 */
const BACKUP_VERSION = 1;

/**
 * Shape of the unencrypted backup data.
 */
export interface BackupData {
  version: number;
  receipts: any[]; // Receipt objects
  mileage: any[]; // MileageEntry objects
  categories?: any; // optional categories data (raw storage shape)
  ledger?: any[]; // optional ledger entries for tamper‑evidence
}

/**
 * Validate the shape of a backup object (not encrypted).
 * Returns null if valid, otherwise an error string.
 */
export function validateBackupStructure(obj: any): string | null {
  if (typeof obj !== 'object' || obj === null) return 'Backup must be an object';
  if (obj.version !== BACKUP_VERSION) return 'Unsupported backup version';
  if (!Array.isArray(obj.receipts)) return 'Receipts must be an array';
  if (!Array.isArray(obj.mileage)) return 'Mileage must be an array';
  for (const r of obj.receipts) {
    if (typeof r !== 'object' || r === null) return 'Invalid receipt entry';
    if (typeof r.id !== 'string') return 'Receipt id must be string';
    if (typeof r.amount !== 'number') return 'Receipt amount must be number';
    if (typeof r.date !== 'string') return 'Receipt date must be string';
    if (typeof r.category !== 'string') return 'Receipt category must be string';
    if (typeof r.type !== 'string') return 'Receipt type must be string';
    if (typeof r.notes !== 'string') return 'Receipt notes must be string';
  }
  for (const m of obj.mileage) {
    if (typeof m !== 'object' || m === null) return 'Invalid mileage entry';
    if (typeof m.id !== 'string') return 'Mileage id must be string';
    if (typeof m.date !== 'string') return 'Mileage date must be string';
    if (typeof m.miles !== 'number') return 'Mileage miles must be number';
    if (typeof m.purpose !== 'string') return 'Mileage purpose must be string';
  }
  if (obj.categories !== undefined && typeof obj.categories !== 'object') {
    return 'Categories must be an object';
  }
  if (obj.ledger !== undefined && !Array.isArray(obj.ledger)) {
    return 'Ledger must be an array';
  }
  return null;
}

/**
 * Create an encrypted backup string.
 * Includes receipts, mileage, categories and the ledger.
 */
export async function createBackup(store: Store, passphrase: string): Promise<string> {
  const receipts = await getAllReceipts(store);
  const mileage = await getAllMileageEntries(store);
  const rawCategories = await store.get<any>('categories');
  const ledger = await getLedger(store);
  const data: BackupData = {
    version: BACKUP_VERSION,
    receipts,
    mileage,
    categories: rawCategories ?? { custom: [], hidden: [], rename: {} },
    ledger,
  };
  const json = JSON.stringify(data);
  const salt = randomBytes(16);
  const key = deriveKey(passphrase, salt);
  const ciphertext = encryptText(key, json);
  const saltB64 = toBase64(salt);
  return `${saltB64}:${ciphertext}`;
}

/**
 * Restore from an encrypted backup string.
 * Verifies ledger integrity before applying data. Throws a friendly error on failure.
 */
export async function restoreBackup(store: Store, backupString: string, passphrase: string): Promise<void> {
  const [saltB64, cipher] = backupString.split(':');
  if (!saltB64 || !cipher) throw new Error('Invalid backup format');
  const salt = fromBase64(saltB64);
  const key = deriveKey(passphrase, salt);
  let json: string;
  try {
    json = decryptText(key, cipher);
  } catch (e) {
    throw new Error('Backup verification failed: friendly error');
  }
  let obj: any;
  try {
    obj = JSON.parse(json);
  } catch {
    throw new Error('Backup data corrupted');
  }
  const err = validateBackupStructure(obj);
  if (err) throw new Error(err);

  // Verify ledger if present
  if (Array.isArray(obj.ledger)) {
    const verification = await verifyLedger(store, obj.ledger);
    if (!verification.ok) {
      throw new Error('Backup verification failed: friendly error');
    }
  }

  await store.clearAll();
  for (const r of obj.receipts) await store.put('receipts', r);
  for (const m of obj.mileage) await store.put('mileage', m);
  if (obj.categories) await store.set('categories', obj.categories);
  if (Array.isArray(obj.ledger)) {
    await setLedger(store, obj.ledger);
    // Import any records that lack an imported entry (legacy handling)
    await importMissingAsImported(store);
  }
}
"}

{"path": "src/lib/exportCsv.ts", "line_start": 1, "line_end": 200, "content": "import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import type { Receipt, MileageEntry } from './models';
import type { Store } from './storage/types';
import { sha256 } from '@noble/hashes/sha2.js';
import { utf8ToBytes, bytesToHex } from '@noble/hashes/utils.js';
import { appendEntryForExport } from './ledger';
import { getLedger } from './ledgerHelpers';

/** Escape a cell for CSV output according to RFC 4180.
 * Numbers output as plain numbers.
 * null/undefined become empty string.
 * Strings starting with = + - @ or tab are prefixed with a single quote to prevent formula injection.
 * If a string is prefixed, we leave it as-is (no additional quoting) because the prefix already neutralises formulas.
 * Otherwise, double quotes inside the value are escaped by doubling them.
 * If the resulting string contains commas, double quotes, or line breaks, wrap the whole field in double quotes.
 */
function csvEscape(value: any): string {
  if (value === undefined || value === null) return '';
  if (typeof value === 'number') return String(value);
  const original = String(value);
  const needsPrefix = /^[=+\-@\t]/.test(original);
  if (needsPrefix) {
    return "'" + original;
  }
  const escaped = original.replace(/"/g, '""');
  if (/[",\r\n]/.test(escaped)) {
    return `"${escaped}"`;
  }
  return escaped;
}

/** Generate a CSV string containing receipts and mileage entries, with a verification line formatted as
 * "# verification: entries=<N>, headHash=<HASH>, code=<CODE>" where CODE is the first 12 hex chars of the content hash.
 */
export async function generateCsv(store?: Store): Promise<string> {
  const s = store ?? (await (await import('./storage')).getStore());
  const receipts: Receipt[] = await getAllReceipts(s);
  const mileage: MileageEntry[] = await getAllMileageEntries(s);
  const lines: string[] = [];
  lines.push('id,amount,date,category,type,notes');
  for (const r of receipts) {
    lines.push([
      csvEscape(r.id),
      csvEscape(r.amount),
      csvEscape(r.date),
      csvEscape(r.category),
      csvEscape(r.type),
      csvEscape(r.notes),
    ].join(','));
  }
  lines.push('id,miles,date,purpose');
  for (const m of mileage) {
    lines.push([
      csvEscape(m.id),
      csvEscape(m.miles),
      csvEscape(m.date),
      csvEscape(m.purpose),
    ].join(','));
  }
  const contentWithoutVerification = lines.join('\n');
  const hashHex = bytesToHex(sha256(utf8ToBytes(contentWithoutVerification)));
  const code = hashHex.slice(0, 12);
  // Append ledger entry for export
  await appendEntryForExport('csv', code, 0, '', s); // placeholder; real values set inside
  // Re-fetch ledger to get updated headHash and count
  const ledger = await getLedger(s);
  const entriesCount = ledger.length; // includes the newly added export entry
  const headHash = ledger[ledger.length - 1].hash;
  const verificationLine = `# verification: entries=${entriesCount}, headHash=${headHash}, code=${code}`;
  lines.push(verificationLine);
  return lines.join('\n');
}
"}

